(()=>{'use strict';
const $=s=>document.querySelector(s), app=$('#app'),units=window.FINNISH_CURRICULUM,grammar=window.FINNISH_GRAMMAR,sets=window.FINNISH_SETS;
const KEY='finnish-az-sefr-v4';const empty={progress:{},stars:0,saved:[],known:[],missed:[],days:{},custom:[],attempts:0,correct:0};
let db;try{db={...empty,...JSON.parse(localStorage.getItem(KEY)||localStorage.getItem('finnish-az-sefr-v2')||'{}')}}catch{db={...empty}};
for(const k of ['saved','known','missed','custom'])if(!Array.isArray(db[k]))db[k]=[];
if(!db.progress||typeof db.progress!=='object')db.progress={};if(!db.days||typeof db.days!=='object')db.days={};
for(const [oldId,newId] of [['letters','stage-1'],['numbers','stage-2'],['greetings','stage-3']]){if(!db.progress[newId]&&Array.isArray(db.progress[oldId]))db.progress[newId]=[...db.progress[oldId]];}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(db))}catch{toast('امکان ذخیره وجود ندارد')}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s||'').trim().toLocaleLowerCase('fi-FI').replace(/\s+/g,' ').normalize('NFC');
const today=()=>{let d=new Date();return [d.getFullYear(),d.getMonth()+1,d.getDate()].join('-')};
const touch=()=>{db.days[today()]??={activity:0};db.days[today()].activity++;save()};
const streak=()=>{let n=0,d=new Date();if(!db.days[today()])d.setDate(d.getDate()-1);for(let i=0;i<365;i++){let k=[d.getFullYear(),d.getMonth()+1,d.getDate()].join('-');if(!db.days[k])break;n++;d.setDate(d.getDate()-1)}return n};
const prog=i=>{let id=units[i].id;if(!Array.isArray(db.progress[id]))db.progress[id]=[false,false,false,false];return db.progress[id]};
const unlocked=i=>i===0||(!!authUser&&prog(i-1).every(Boolean)); // Email verification unlocks progression, then stages remain sequential.
const done=i=>prog(i).every(Boolean);
const nextUnit=()=>Math.max(0,units.findIndex((u,i)=>unlocked(i)&&!done(i))<0?units.length-1:units.findIndex((u,i)=>unlocked(i)&&!done(i)));
const word=a=>({id:a[0],fi:a[1],fa:a[2],en:a[3],emoji:a[4]||'✨'});
const words=()=>[...new Map([...units.flatMap(u=>u.words),...sets.flatMap(s=>s.words),...(window.FINNISH_EXTRA||[]),...db.custom.map(x=>[x.id,x.fi,x.fa,x.en,x.emoji||'✨'])].map(a=>[a[0],word(a)])).values()];
const findWord=id=>words().find(w=>w.id===id);
const stars=()=>db.stars||0;
const unitArt=i=>i===0?'<span class="letter-art"><i>A</i><i>Ö</i><i>Ä</i></span>':i===1?'<span class="number-art"><i>1</i><i>2</i><i>3</i></span>':esc(units[i].icon);
const stageNames=['آموزش و فلش‌کارت','گوش دادن','بازی تطبیق','آزمون و نوشتن'];const stageIcons=['📖','🎧','🎮','📝'];
const s={tab:'home',unit:0,phase:0,wi:0,q:0,questions:[],score:0,choice:null,finished:false,passed:false,mode:'',cat:'',filter:'all',search:'',speed:'slow',grammar:0,scanFile:null,scanUrl:'',scanText:'',matches:[],unknown:[],busy:false,typing:'',gameType:'match',memCards:[],memOpen:[],memMatched:[],memBusy:false,memMoves:0,gameSound:true,spellPicked:[],spellTiles:[],truePairs:[],quizLevel:'A1',quizMode:'level',quizQuestions:[],quizIndex:0,quizChoice:null,quizScore:0,quizDone:false};
try{s.speed=localStorage.getItem('finnish-speed-v11')||'slow';s.gameSound=localStorage.getItem('finnish-game-sound')!=='off'}catch{}
let toastTimeout;function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>t.classList.remove('show'),2600)}
// Speech is initiated only from a direct tap (important on iOS Safari / home-screen PWA).
let audioContext=null,voiceWarned=false;
function speech(text){
 text=String(text||'').trim();if(!text)return;
 if(/^[A-ZÅÄÖ]$/.test(text))text=text.toLocaleLowerCase('fi-FI');
 if(!('speechSynthesis'in window)){toast('پخش گفتار در این مرورگر پشتیبانی نمی‌شود');return}
 try{
  const synth=window.speechSynthesis;
  synth.cancel();
  const utter=new SpeechSynthesisUtterance(text);
  utter.lang='fi-FI';utter.rate=s.speed==='slow'?.55:.72;utter.pitch=1.17;utter.volume=1;
  const voices=synth.getVoices(),fi=voices.filter(v=>/^fi(?:-|$)/i.test(v.lang));
  if(fi.length){utter.voice=fi.find(v=>/premium|enhanced|natural/i.test(v.name))||fi.find(v=>/satu|helena|selma|anna|siri/i.test(v.name))||fi[0]}
  else if(!voiceWarned){voiceWarned=true;toast('صدای فنلاندی روی این دستگاه در دسترس نیست')}
  utter.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')toast('تلفظ پخش نشد؛ دوباره امتحان کن')};
  synth.speak(utter);
  // Some Safari versions temporarily pause synthesis after navigating the PWA.
  if(synth.paused)synth.resume();
 }catch(e){console.warn('Finnish TTS',e);toast('پخش تلفظ انجام نشد')}
}
function gameTone(success=true){
 if(!s.gameSound)return;
 try{
  const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;
  if(!audioContext)audioContext=new AC();
  if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});
  const now=audioContext.currentTime,osc=audioContext.createOscillator(),gain=audioContext.createGain();
  osc.type='sine';osc.frequency.setValueAtTime(success?660:260,now);
  if(success)osc.frequency.exponentialRampToValueAtTime(880,now+.13);
  else osc.frequency.exponentialRampToValueAtTime(190,now+.17);
  gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(.09,now+.015);gain.gain.exponentialRampToValueAtTime(.0001,now+.23);
  osc.connect(gain);gain.connect(audioContext.destination);osc.start(now);osc.stop(now+.24);
 }catch(e){console.warn('Game audio',e)}
}

function go(tab,scroll=true){s.tab=tab;render();if(scroll)window.scrollTo({top:0,behavior:'instant'})}
function meter(v){return `<div class="meter"><span style="width:${Math.min(100,Math.max(0,v))}%"></span></div>`}
function button(label,act,cls='primary'){return `<button class="btn ${cls}" data-action="${act}">${label}</button>`}
function controls(){return `<div class="voice-controls"><span>🔊 سرعت تلفظ</span><button data-speed="clear" class="${s.speed==='clear'?'active':''}">آرام</button><button data-speed="slow" class="${s.speed==='slow'?'active':''}">آهسته‌تر</button></div>`}
function headerUpdate(){let a=$('#starCounter'),b=$('#streakCounter');if(a)a.textContent='⭐ '+stars();if(b)b.textContent='🔥 '+streak()}
function navUpdate(){document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===(['lesson','practice','success'].includes(s.tab)?'path':s.tab==='category'?'more':s.tab==='mini'?'games':s.tab==='grammarDetail'?'grammar':s.tab==='scan'?'more':s.tab==='stats'?'more':s.tab==='profile'?'more':s.tab))) }
function levelChip(u){return `<span class="level-chip">${esc(u.level)}</span>`}
function unitCard(u,i){let locked=!unlocked(i),p=prog(i).filter(Boolean).length;return `<button class="path-card ${locked?'is-locked':''} ${done(i)?'is-done':''}" data-unit="${i}" ${locked?'disabled':''}><span class="path-bubble">${locked?'🔒':i+1}</span><span class="path-art">${unitArt(i)}</span><span class="path-content"><small>${levelChip(u)} مرحله ${i+1}</small><strong>${esc(u.title)}</strong><em>${esc(u.sub)}</em>${meter(p*25)}</span><span class="path-arrow">${locked?'🔐':done(i)?'✓':'›'}</span></button>`}
function guestLock(){return `<span class="guest-lock">🔒 پس از تأیید ایمیل</span>`}
function registerHint(){return `<div class="guest-invite">🔓 برای باز شدن بخش‌های بیشتر، ایمیلت را ثبت و تأیید کن. <button class="btn primary" data-tab="profile">ثبت‌نام یا ورود</button></div>`}
function renderHome(){let i=nextUnit(),u=units[i];return `<section class="home-welcome"><div class="hero-person hero-merged"><img class="person-image" src="./home-guide.webp" alt="راهنمای کارتونی آموزش فنلاندی"><div class="speech-bubble"><b>Tervetuloa!</b><span>به دنیای فنلاندی خوش اومدی!</span><button class="welcome-audio" data-speak="Tervetuloa!" aria-label="تلفظ خوش‌آمدگویی">🔊 بشنو</button></div></div><h1>هر روز یک قدم به فنلاندی نزدیک‌تر 🇫🇮</h1><p>آموزش رایگان، بازی و آزمون؛ بدون تبلیغات مزاحم</p></section><section class="feature-panel"><div class="section-title"><h2>✨ ادامه یادگیری</h2><span>${levelChip(u)}</span></div><div class="featured-row"><span class="feature-art">${unitArt(i)}</span><div><small>مرحله ${i+1} از ۵۰</small><strong>${esc(u.title)}</strong><p>${esc(u.sub)}</p>${meter(prog(i).filter(Boolean).length*25)}</div></div>${button('شروع / ادامه مرحله ←','continue')}</section><div class="section-title"><h2>امروز چی یاد بگیریم؟</h2></div><div class="quick-grid"><button data-tab="path" class="quick blue"><span>🗺️</span><strong>مسیر ۵۰ مرحله‌ای</strong></button><button data-tab="games" class="quick green"><span>🎮</span><strong>بازی‌ها</strong></button><button data-tab="grammar" class="quick purple"><span>📚</span><strong>گرامر</strong></button><button data-tab="scan" class="quick cyan"><span>📸</span><strong>دوربین لغات</strong></button><button data-tab="category" class="quick orange"><span>🧩</span><strong>دسته‌بندی لغات</strong></button><button data-tab="stats" class="quick rose"><span>🏆</span><strong>پیشرفت من</strong></button></div><div class="section-title"><h2>🛤️ مرحله‌های بعدی</h2><button class="text-btn" data-tab="path">مشاهده همه ←</button></div><div class="home-path">${units.slice(Math.max(0,i-1),Math.min(units.length,i+3)).map(u=>unitCard(u,units.indexOf(u))).join('')}</div>`}
function renderPath(){return `<div class="page-head"><span class="overline">LEARNING PATH · A0 → B1</span><h1>🗺️ مسیر یادگیری</h1><p>از الفبا شروع کن؛ هر مرحله پس از قبولی در آزمون مرحله قبل باز می‌شود.</p></div><div class="path-legend"><span>🟢 باز</span><span>🔒 قفل</span><span>⭐ تکمیل</span></div>${!authUser?registerHint():''}<div class="path-timeline">${units.map((u,i)=>`${i===0||i===20||i===30||i===47?`<div class="level-break">${i===0?'شروع از صفر · A0':i===20?'واژگان و مکالمه · A1':i===30?'زندگی روزمره · A2':'آشنایی با B1'}</div>`:''}${unitCard(u,i)}`).join('')}</div>`}
function renderLesson(){let u=units[s.unit],p=prog(s.unit);return `<div class="page-head"><button class="back" data-tab="path">→ بازگشت به مسیر</button><span class="overline">مرحله ${s.unit+1} / ۵۰ · ${esc(u.level)}</span><h1>${esc(u.icon)} ${esc(u.title)}</h1><p>${esc(u.note)}</p>${meter(p.filter(Boolean).length*25)}</div><div class="stage-grid">${stageNames.map((n,i)=>{let lock=i>0&&!p[i-1];return `<button class="stage-tile ${p[i]?'completed':''} ${lock?'locked':''}" data-phase="${i}" ${lock?'disabled':''}><span>${lock?'🔒':p[i]?'✅':stageIcons[i]}</span><strong>${n}</strong><small>${lock?'مرحله قبلی را تمام کن':p[i]?'تکمیل شده':'شروع تمرین'}</small></button>`}).join('')}</div>`}
function unitWords(){return units[s.unit].words.map(word)}
function renderStudy(){let ws=unitWords(),w=ws[s.wi]||ws[0];return `<div class="page-head"><button class="back" data-action="backLesson">→ بخش‌های مرحله</button><h1>📖 آموزش و فلش‌کارت</h1><p>${esc(units[s.unit].title)} · ${s.wi+1} از ${ws.length}</p>${meter(s.wi/ws.length*100)}</div>${controls()}<div class="big-flashcard"><div class="flash-emoji">${unitArt(s.unit)}</div><strong class="flash-fi" lang="fi" dir="ltr">${s.unit===0?`${esc(w.fi)} <span class="letter-lower">${esc(w.fi.toLocaleLowerCase('fi-FI'))}</span>`:esc(w.fi)}</strong><span class="flash-fa">${esc(w.fa)}</span>${s.unit===0?'':`<small lang="en" dir="ltr">${esc(w.en)}</small>`}<button class="audio-button" data-speak="${esc(w.fi)}" aria-label="تلفظ">🔊</button></div><div class="study-tip">روی 🔊 بزن و با سرعت عادی یا آهسته گوش کن.</div>${button('✓ بلدم · کلمه بعدی','knowNext','green')}`}
function makeQuestions(){let ws=unitWords(),arr=[...ws].sort(()=>Math.random()-.5);let pool=ws.length>=5?arr.slice(0,5):[...arr,...arr].slice(0,5);return pool.map((w,i)=>{let others=ws.filter(x=>x.id!==w.id).sort(()=>Math.random()-.5).slice(0,3);return {w,opts:[w,...others].sort(()=>Math.random()-.5),written:s.phase===3&&i>=3}})}
function beginPhase(i){if(i>0&&!prog(s.unit)[i-1])return toast('ابتدا بخش قبلی را کامل کن');s.phase=i;s.wi=0;s.q=0;s.score=0;s.choice=null;s.finished=false;s.passed=false;s.typing='';s.questions=i===0?[]:makeQuestions();go('practice')}
function renderQuestion(){let item=s.questions[s.q],w=item.w;let isListen=s.phase===1,writing=item.written;let prompt=s.phase===1?'کدام واژه را شنیدی؟':s.phase===2?'معنی این واژه چیست؟':writing?'کلمه فنلاندی را بنویس':'معنی درست را انتخاب کن';return `<div class="page-head"><button class="back" data-tab="${s.tab==='mini'?'games':'lesson'}">→ بازگشت</button><span class="overline">${esc(stageNames[s.phase])} · ${s.q+1} / ${s.questions.length}</span><h1>${esc(prompt)}</h1>${meter((s.q+1)/s.questions.length*100)}</div>${controls()}<div class="question-card">${isListen?`<button class="giant-sound" data-speak="${esc(w.fi)}">🔊</button><p>به تلفظ گوش کن و پاسخ بده</p>`:`<div class="question-emoji">${esc(units[s.unit].icon)}</div><strong class="question-word" lang="fi" dir="ltr">${writing?esc(w.fa):esc(w.fi)}</strong>${!writing?`<button class="question-play" data-speak="${esc(w.fi)}" aria-label="تلفظ کلمه فنلاندی">🔊 تلفظ</button>`:''}`}</div>${writing?`<form id="writeForm"><label for="writeInput">پاسخ به فنلاندی:</label><input id="writeInput" class="answer-input" dir="ltr" lang="fi" autocomplete="off" spellcheck="false" placeholder="Kirjoita suomeksi..." value="${esc(s.typing)}" ${s.choice!==null?'disabled':''}><button class="btn primary" type="submit" ${s.choice!==null?'disabled':''}>بررسی پاسخ</button></form>`:`<div class="answer-grid">${item.opts.map(x=>{let label=isListen?x.fi:x.fa;let selected=s.choice===x.id;let correct=s.choice!==null&&x.id===w.id;return `<button data-answer="${esc(x.id)}" class="answer-option ${correct?'right':selected?'wrong':''}" ${s.choice!==null?'disabled':''}>${esc(label)}</button>`}).join('')}</div>`}${s.choice!==null?`<div class="feedback ${s.choice===w.id?'good':'bad'}">${s.choice===w.id?'✓ آفرین! درست بود.':'پاسخ درست: '+esc(w.fi)+' — '+esc(w.fa)}</div><button class="question-play" data-speak="${esc(w.fi)}">🔊 شنیدن پاسخ درست</button>${button(s.q===s.questions.length-1?'دیدن نتیجه ←':'سؤال بعدی ←','nextQuestion','primary')}`:''}`}
function renderResult(){return `<section class="result-card"><div class="result-stars">${s.passed?'🌟 ⭐ 🌟':'💪'}</div><h1>${s.passed?(s.tab==='mini'?'آفرین! بازی رو بردی':'آفرین! مرحله کامل شد'):'یه بار دیگه تمرین کنیم!'}</h1><p>پاسخ درست: ${s.score} از ${s.questions.length}</p><p>${s.tab==='mini'?'می‌توانی سؤال‌های جدید بگیری یا همین بازی را تکرار کنی.':s.passed?'بخش بعدی برایت باز شد.':'برای قبولی بیشتر پاسخ‌ها باید درست باشند.'}</p>${s.tab==='mini'?`<div class="quiz-actions">${button('✨ بازی جدید','miniAgain')}${button('🔁 تکرار همین بازی','miniSame','secondary')}${button('بازگشت به بازی‌ها','miniBack','secondary')}</div>`:button(s.passed?'ادامه مسیر ←':'تکرار تمرین','resultNext',s.passed?'green':'primary')}</section>`}
function renderPractice(){return s.phase===0?renderStudy():s.finished?renderResult():renderQuestion()}
function answer(id){if(s.choice!==null)return;let w=s.questions[s.q].w;gameTone(id===w.id);if(s.tab==='mini')speech(w.fi);s.choice=id;db.attempts++;if(id===w.id){s.score++;db.correct++;db.missed=db.missed.filter(x=>x!==w.id)}else if(!db.missed.includes(w.id))db.missed.push(w.id);touch();render()}
function finishPhase(){if(s.phase===0||s.score>=4){let p=prog(s.unit);if(!p[s.phase]){p[s.phase]=true;db.stars+=s.phase===3?10:2;if(s.phase===3&&p.every(Boolean))db.stars+=10;touch()}s.passed=true}else s.passed=false;s.finished=true;save();render()}
// V10: independent 10-question four-option practice. No social-media content is copied here.
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function quizVocabulary(level){
 const allowed=level==='A1'?['A0','A1']:level==='A2'?['A2']:['B1'];
 const raw=units.filter(u=>allowed.includes(u.level)).flatMap(u=>u.words.map(word));
 if(level==='A1')raw.push(...sets.flatMap(c=>c.words.map(word)));
 const unique=new Map();
 for(const w of raw){const fi=norm(w.fi);if(!fi||fi.length===1||!w.fa||!w.en||unique.has(fi))continue;unique.set(fi,w)}
 return [...unique.values()];
}
function quizPool(mode,level){
 if(mode==='review')return [...new Map(db.missed.map(findWord).filter(w=>w&&norm(w.fi).length>1).map(w=>[norm(w.fi),w])).values()];
 return quizVocabulary(level);
}
function startQuiz(mode='level',level='A1',same=false){
 if(same&&s.quizQuestions.length){s.quizIndex=0;s.quizScore=0;s.quizChoice=null;s.quizDone=false;go('quiz');return}
 const target=quizPool(mode,level);
 if(!target.length){toast('هنوز لغتی برای مرور اشتباهات وجود ندارد');return}
 const all=[...new Map([...quizVocabulary('A1'),...quizVocabulary('A2'),...quizVocabulary('B1'),...target].map(w=>[norm(w.fi),w])).values()];
 s.quizMode=mode;s.quizLevel=level;s.quizIndex=0;s.quizScore=0;s.quizChoice=null;s.quizDone=false;
 s.quizQuestions=shuffle(target).slice(0,10).map((w,i)=>{
   // Alternate the direction so the learner actively recalls both translations.
   const direction=i%2===0?'fa':'fi';
   const answerLabel=x=>direction==='fa'?x.fa:x.fi;
   const used=new Set([norm(answerLabel(w))]);
   const distractors=[];
   for(const x of shuffle(all)){
     if(x.id===w.id)continue;
     const label=norm(answerLabel(x));
     if(!label||used.has(label))continue;
     used.add(label);distractors.push(x);
     if(distractors.length===3)break;
   }
   return {w,direction,options:shuffle([w,...distractors])};
 });
 go('quiz');
}
function quizAnswer(id){
 if(s.quizChoice!==null||s.quizDone)return;
 const q=s.quizQuestions[s.quizIndex];if(!q)return;
 s.quizChoice=id;const good=id===q.w.id;
 if(good){s.quizScore++;db.correct=(db.correct||0)+1;db.missed=db.missed.filter(x=>x!==q.w.id)}
 else if(!db.missed.includes(q.w.id))db.missed.push(q.w.id);
 db.attempts=(db.attempts||0)+1;
 gameTone(good);touch();render();
}
function quizNext(){
 if(s.quizChoice===null)return;
 if(s.quizIndex+1>=s.quizQuestions.length){s.quizDone=true;db.stars=(db.stars||0)+Math.floor(s.quizScore/5);save()}
 else{s.quizIndex++;s.quizChoice=null}
 render();
}
function renderQuiz(){
 if(s.quizDone){const n=s.quizQuestions.length;return `<button class="back" data-tab="games">→ بازی‌ها</button><section class="quiz-finish"><span class="quiz-finish-icon">🏆</span><h1>آزمون تمام شد!</h1><p class="quiz-score">${s.quizScore} از ${n}</p><p>${s.quizScore===n?'عالی! همه پاسخ‌ها درست بود.':'می‌تونی دوباره امتحان بدی و لغت‌های اشتباه رو مرور کنی.'}</p><div class="quiz-actions"><button class="btn primary" data-action="quizAgain">✨ آزمون جدید</button><button class="btn secondary" data-action="quizSame">🔁 تکرار همین سؤال‌ها</button><button class="btn secondary" data-action="quizReview">🧠 مرور اشتباهات</button><button class="btn secondary" data-tab="games">بازگشت به بازی‌ها</button></div></section>`}
 const q=s.quizQuestions[s.quizIndex];if(!q)return `<div class="empty">سؤالی پیدا نشد.</div>`;
 const checked=s.quizChoice!==null;
 const question=q.direction==='fa'?`معنی فارسی «${esc(q.w.fi)}» چیست؟`:`«${esc(q.w.fa)}» به فنلاندی چی می‌شود؟`;
 return `<button class="back" data-tab="games">→ بازی‌ها</button><div class="page-head"><span class="overline">${s.quizMode==='review'?'مرور اشتباهات':'آزمون '+esc(s.quizLevel)} · ${s.quizIndex+1} از ${s.quizQuestions.length}</span><h1>🧠 خودت رو امتحان کن!</h1>${meter((s.quizIndex+1)/s.quizQuestions.length*100)}</div><section class="quiz-panel"><h2 class="quiz-prompt">${question}</h2>${q.direction==='fa'?`<button class="question-play" data-speak="${esc(q.w.fi)}">🔊 شنیدن تلفظ</button>`:''}<div class="quiz-options">${q.options.map((x,i)=>`<button data-quiz-answer="${esc(x.id)}" class="quiz-option ${checked&&x.id===q.w.id?'right':checked&&x.id===s.quizChoice?'wrong':''}" ${checked?'disabled':''}><span class="quiz-option-index">${['۱','۲','۳','۴'][i]}</span><span dir="${q.direction==='fa'?'rtl':'ltr'}">${esc(q.direction==='fa'?x.fa:x.fi)}</span></button>`).join('')}</div>${checked?`<div class="quiz-feedback ${s.quizChoice===q.w.id?'good':'bad'}"><strong>${s.quizChoice===q.w.id?'✓ درست جواب دادی!':'✕ پاسخ درست رو ببین'}</strong><p><b lang="fi" dir="ltr">${esc(q.w.fi)}</b> — ${esc(q.w.fa)} <span dir="ltr">(${esc(q.w.en)})</span></p><button class="question-play" data-speak="${esc(q.w.fi)}">🔊 تلفظ فنلاندی</button></div><button class="btn primary quiz-next" data-action="quizNext">${s.quizIndex===s.quizQuestions.length-1?'مشاهده نتیجه ←':'سؤال بعدی ←'}</button>`:''}</section>`;
}

function renderGames(){return `<div class="page-head"><h1>🎮 بازی‌های فنلاندی</h1><p>کلمات فنلاندی را با صدا تمرین کن؛ هر چند بار دوست داری بازی کن.</p></div><div class="quiz-launch"><h2>🧠 خودت رو امتحان کن!</h2><p>۱۰ سؤال چهارگزینه‌ای با معنی و تلفظ. سطح A1 برای همه باز است.</p><div class="quiz-levels"><button data-quiz-level="A1">A1 · پایه</button><button data-quiz-level="A2" ${!authUser?'disabled class="is-locked"':''}>${authUser?'A2 · متوسط':'🔒 A2 · متوسط'}</button><button data-quiz-level="B1" ${!authUser?'disabled class="is-locked"':''}>${authUser?'B1 · مقدماتی':'🔒 B1 · مقدماتی'}</button><button data-quiz-review="1" ${!authUser?'disabled class="is-locked"':''}>${authUser?'🔁 مرور اشتباهات':'🔒 مرور اشتباهات'}</button></div></div><h2 class="small-title">بازی‌های دیگر</h2><div class="game-choices"><button data-game="match" class="game-tile"><span>🧩</span><strong>کلمه و معنی</strong><small>۵ سؤال سریع</small></button><button data-game="listen" class="game-tile" ${!authUser?'disabled':''}><span>🎧</span><strong>چی شنیدی؟</strong><small>تلفظ و انتخاب</small></button><button data-game="memory" class="game-tile" ${!authUser?'disabled':''}><span>🃏</span><strong>حافظه واژگان</strong><small>بازی تمرکزی</small></button><button data-game="truefalse" class="game-tile" ${!authUser?'disabled':''}><span>✅</span><strong>درست یا غلط؟</strong><small>۵ چالش معنی</small></button><button data-game="spell" class="game-tile" ${!authUser?'disabled':''}><span>🔤</span><strong>کلمه‌سازی</strong><small>حروف را مرتب کن</small></button></div>${!authUser?registerHint():''}`}
function makeMiniQuestions(){
 const raw=authUser?[...quizVocabulary('A1'),...quizVocabulary('A2'),...quizVocabulary('B1')]:quizVocabulary('A1');
 const pool=[...new Map(raw.filter(w=>w.fi&&w.fa).map(w=>[norm(w.fi),w])).values()];
 const selected=shuffle(pool).slice(0,5);
 return selected.map(w=>({w,opts:shuffle([w,...shuffle(pool.filter(x=>x.id!==w.id)).slice(0,3)]),written:false}));
}
function startMini(type,same=false){s.gameType=type;s.mode='mini';s.q=0;s.score=0;s.choice=null;s.finished=false;s.passed=false;s.phase=type==='listen'?1:2;let ix=Math.min(nextUnit(),units.length-1);s.unit=ix;s.questions=same&&s.lastMiniType===type&&s.lastMiniQuestions?.length?s.lastMiniQuestions.map(q=>({...q})):makeMiniQuestions();if(type==='truefalse'){const ws=s.questions.map(x=>x.w);s.truePairs=s.questions.map((it,i)=>{const wrong=ws.filter(w=>w.id!==it.w.id);const correct=i%2===0||!wrong.length;return {shown:correct?it.w:wrong[(i*3)%wrong.length],correct}})}
if(type==='spell'&&!same){const eligible=[...new Map(units.slice(1,8).flatMap(u=>u.words).map(word).filter(w=>/^[a-zåäö]{3,12}$/i.test(w.fi)).map(w=>[w.fi,w])).values()];if(eligible.length){s.questions=[...eligible].sort(()=>Math.random()-.5).slice(0,5).map(w=>({w,opts:[]}))}else{toast('این درس کلمه مناسب برای کلمه‌سازی ندارد');return}setupSpell()}
if(type==='memory'){let picks=same&&s.lastMemoryPicks?.length?s.lastMemoryPicks:shuffle(quizVocabulary('A1')).slice(0,4);s.lastMemoryPicks=picks;s.memCards=picks.flatMap(w=>[{key:w.id+'-fi',id:w.id,text:w.fi,isFi:true},{key:w.id+'-fa',id:w.id,text:w.fa,isFi:false}]).sort(()=>Math.random()-.5);s.memOpen=[];s.memMatched=[];s.memBusy=false;s.memMoves=0;}s.lastMiniType=type;s.lastMiniQuestions=s.questions.map(q=>({...q}));if(type==='spell'&&same)setupSpell();go('mini')}
function setupSpell(){s.spellPicked=[];const w=s.questions[s.q]?.w;if(!w)return;const chars=[...w.fi.toLocaleLowerCase('fi-FI')];s.spellTiles=chars.map((ch,i)=>({ch,i})).sort(()=>Math.random()-.5);if(s.spellTiles.map(t=>t.ch).join('')===chars.join('')&&s.spellTiles.length>1)s.spellTiles.reverse()}
function renderTrueFalse(){const it=s.questions[s.q],pair=s.truePairs[s.q],correct=pair.correct,chosen=s.choice;return `<div class="page-head"><h1>✅ درست یا غلط؟</h1><p>سؤال ${s.q+1} از ${s.questions.length}</p>${meter((s.q+1)/s.questions.length*100)}</div><div class="question-card"><strong class="question-word" lang="fi" dir="ltr">${esc(it.w.fi)}</strong><p>آیا معنی آن «${esc(pair.shown.fa)}» است؟</p><button class="question-play" data-speak="${esc(it.w.fi)}">🔊 تلفظ</button></div><div class="answer-grid"><button class="answer-option" data-truefalse="yes" ${chosen!==null?'disabled':''}>✓ درست</button><button class="answer-option" data-truefalse="no" ${chosen!==null?'disabled':''}>✕ غلط</button></div>${chosen!==null?`<div class="feedback ${chosen===it.w.id?'good':'bad'}">${chosen===it.w.id?'آفرین!':'معنی درست: '+esc(it.w.fa)}</div>${button('سؤال بعدی ←','nextQuestion')}`:''}`}
function renderSpell(){const w=s.questions[s.q].w,done=s.choice!==null;const built=s.spellPicked.map(i=>s.spellTiles[i].ch).join('');return `<div class="page-head"><h1>🔤 کلمه‌سازی</h1><p>سؤال ${s.q+1} از ${s.questions.length}</p>${meter((s.q+1)/s.questions.length*100)}</div><div class="question-card"><p>کلمه فنلاندی «${esc(w.fa)}» را بساز</p><button class="question-play" data-speak="${esc(w.fi)}">🔊 گوش کن</button><div class="spelling-result" lang="fi" dir="ltr">${esc(built)||'···'}</div></div><div class="letter-tiles" dir="ltr">${s.spellTiles.map((t,i)=>`<button data-letter="${i}" ${s.spellPicked.includes(i)||done?'disabled':''}>${esc(t.ch)}</button>`).join('')}</div><div class="spelling-actions"><button class="btn secondary" data-action="spellBack" ${!s.spellPicked.length||done?'disabled':''}>⌫ حذف حرف</button><button class="btn primary" data-action="spellCheck" ${!s.spellPicked.length||done?'disabled':''}>بررسی</button></div>${done?`<div class="feedback ${s.choice===w.id?'good':'bad'}">${s.choice===w.id?'عالی، درست ساختی!':'پاسخ درست: '+esc(w.fi)}</div>${button('سؤال بعدی ←','nextQuestion')}`:''}`}
function renderMini(){if(s.gameType==='truefalse')return `<button class="back" data-tab="games">→ بازی‌ها</button>${s.finished?renderResult():renderTrueFalse()}`;if(s.gameType==='spell')return `<button class="back" data-tab="games">→ بازی‌ها</button>${s.finished?renderResult():renderSpell()}`;if(s.gameType==='memory')return `<button class="back" data-tab="games">→ بازی‌ها</button><div class="page-head"><h1>🃏 بازی حافظه</h1><p>۴ جفت کلمه فنلاندی و معنی فارسی را پیدا کن · ${s.memMatched.length/2} از ۴ جفت</p></div>${s.finished?`<div class="result-card"><div class="result-stars">🌟</div><h1>عالی! همه جفت‌ها پیدا شد</h1><p>${s.memMoves} حرکت انجام دادی.</p><div class="quiz-actions">${button('✨ بازی جدید','miniAgain','primary')}${button('🔁 تکرار همین بازی','miniSame','secondary')}${button('بازگشت به بازی‌ها','miniBack','secondary')}</div></div>`:`<div class="memory-grid">${s.memCards.map((c,i)=>{let shown=s.memOpen.includes(i)||s.memMatched.includes(i);return `<button class="memory-card ${shown?'revealed':''} ${s.memMatched.includes(i)?'matched':''}" data-memory="${i}" ${s.memMatched.includes(i)||s.memBusy?'disabled':''}>${shown?`${c.isFi?'🔊 ':''}${esc(c.text)}`:'❔'}</button>`}).join('')}</div>`}`;return `<button class="back" data-tab="games">→ بازی‌ها</button><div class="page-head"><h1>${s.gameType==='listen'?'🎧 چی شنیدی؟':'🧩 کلمه و معنی'}</h1><p>تمرین آزاد · ۵ سؤال</p></div>${s.finished?renderResult():renderQuestion()}`}
function flipMemory(i){if(s.memBusy||s.memMatched.includes(i)||s.memOpen.includes(i))return;const card=s.memCards[i];if(card.isFi)speech(card.text);s.memOpen.push(i);if(s.memOpen.length===2){s.memMoves++;let [a,b]=s.memOpen;if(s.memCards[a].id===s.memCards[b].id){gameTone(true);s.memMatched.push(a,b);s.memOpen=[];if(s.memMatched.length===s.memCards.length){s.finished=true;s.passed=true;db.stars+=2;touch()}}else{gameTone(false);s.memBusy=true;setTimeout(()=>{s.memOpen=[];s.memBusy=false;if(s.tab==='mini'&&s.gameType==='memory')render()},900)}}render()}
function categorySets(){return [...sets,{id:'alphabet',title:'حروف الفبا',emoji:'🔤',words:units[0].words},{id:'numbers',title:'اعداد',emoji:'🔢',words:units[1].words},{id:'greetings',title:'کلمات ساده',emoji:'💬',words:units[2].words},{id:'family',title:'خانواده',emoji:'👨‍👩‍👧',words:units[4].words}]}
function renderCategories(){return `<div class="page-head"><h1>🧩 دسته‌بندی واژگان</h1><p>لغات موضوعی، جدا از مسیر آموزشی. هر کلمه را گوش کن و برای مرور ذخیره کن.</p></div><div class="category-grid">${categorySets().map((c,i)=>`<button class="category-tile" data-cat="${esc(c.id)}" ${!authUser&&i>0?'disabled':''}><span>${esc(c.emoji)}</span><strong>${esc(c.title)}</strong>${!authUser&&i>0?guestLock():''}</button>`).join('')}</div>${!authUser?registerHint():''}` }
function renderCategory(){let c=categorySets().find(x=>x.id===s.cat);if(!c)return renderCategories();let ws=c.words.map(word).filter(w=>s.filter==='known'?db.known.includes(w.id):s.filter==='unknown'?!db.known.includes(w.id):true);return `<button class="back" data-tab="category">→ دسته‌بندی‌ها</button><div class="page-head"><h1>${esc(c.emoji)} ${esc(c.title)}</h1><p>برای شنیدن روی 🔊 بزن.</p></div>${controls()}<div class="filters"><button data-filter="all" class="${s.filter==='all'?'selected':''}">همه</button><button data-filter="known" class="${s.filter==='known'?'selected':''}">بلدم</button><button data-filter="unknown" class="${s.filter==='unknown'?'selected':''}">بلد نیستم</button></div>${ws.length?ws.map(w=>wordRow(w)).join(''):'<div class="empty">در این دسته کلمه‌ای نیست.</div>'}`}
function wordRow(w){return `<div class="vocab-row"><button class="vocab-speak" data-speak="${esc(w.fi)}">🔊</button><div class="vocab-info"><strong dir="ltr" lang="fi">${esc(w.fi)}${/^[A-ZÅÄÖ]$/.test(w.fi)?` <span class="letter-small-inline">${esc(w.fi.toLocaleLowerCase('fi-FI'))}</span>`:''}</strong><span>${esc(w.fa)} <small dir="ltr">· ${esc(w.en)}</small></span></div><button class="known-btn ${db.known.includes(w.id)?'yes':''}" data-known="${esc(w.id)}">${db.known.includes(w.id)?'✓ بلدم':'بلدم'}</button><button class="save-btn" data-save="${esc(w.id)}">${db.saved.includes(w.id)?'♥':'♡'}</button></div>`}
function renderGrammar(){return `<div class="page-head"><h1>📚 گرامر قدم‌به‌قدم</h1><p>قواعد را هم‌زمان با پیشرفت در درس‌ها یاد بگیر؛ با توضیح ساده فارسی و مثال فنلاندی.</p></div><div class="grammar-list">${grammar.map((g,i)=>{let locked=!authUser&&i>0;return `<button class="grammar-card ${locked?'locked':''}" data-grammar="${i}" ${locked?'disabled':''}><span class="grammar-icon">${locked?'🔒':'📘'}</span><span><strong>${esc(g.title)}</strong></span><b>›</b></button>`}).join('')}</div>${!authUser?registerHint():''}` }
function renderGrammarDetail(){let g=grammar[s.grammar];return `<button class="back" data-tab="grammar">→ فهرست گرامر</button><div class="page-head"><h1>📘 ${esc(g.title)}</h1></div><div class="grammar-explain">${esc(g.rule)}</div><h2 class="small-title">مثال‌ها</h2>${g.examples.map(x=>`<div class="grammar-example"><button data-speak="${esc(x[0])}">🔊</button><div><strong dir="ltr" lang="fi">${esc(x[0])}</strong><p>${esc(x[1])}</p></div></div>`).join('')}${controls()}`}
function renderMore(){return `<div class="page-head"><h1>✨ بیشتر</h1><p>حساب، واژه‌های شخصی و تنظیمات</p></div><div class="more-list"><button data-tab="profile">👤 پروفایل من <b>›</b></button><button data-tab="saved">❤️ واژه‌های ذخیره‌شده <b>›</b></button>${supportEnabled()?'<button data-tab="support">💬 پشتیبانی و ارسال پیام <b>›</b></button>':''}<button data-tab="settings">⚙️ تنظیمات و تلفظ <b>›</b></button><button data-action="enablePush">🔔 فعال‌کردن اعلان‌ها <b>›</b></button></div><div class="social-links"><p>صفحه‌های رسمی Finnish az Sefr</p><a href="https://www.instagram.com/finnish.azsefr/" target="_blank" rel="noopener noreferrer">📸 اینستاگرام آموزش لغات ↗</a><a href="https://www.youtube.com/@finnishazsefr" target="_blank" rel="noopener noreferrer">▶️ یوتیوب آموزش فنلاندی ↗</a><a href="./privacy.html">🔐 حریم خصوصی</a></div>`}
function renderSaved(){let ws=db.saved.map(findWord).filter(Boolean);return `<button class="back" data-tab="more">→ بیشتر</button><div class="page-head"><h1>❤️ واژه‌های من</h1><p>${ws.length} واژه ذخیره‌شده</p></div>${controls()}${ws.length?ws.map(wordRow).join(''):'<div class="empty">هنوز واژه‌ای ذخیره نکردی. روی ♡ کنار کلمه‌ها بزن.</div>'}<h2 class="small-title">اضافه کردن کلمه</h2><form id="customForm" class="custom-form"><input id="customFi" dir="ltr" placeholder="کلمه فنلاندی" required maxlength="60"><input id="customFa" placeholder="معنی فارسی" required maxlength="80"><input id="customEn" dir="ltr" placeholder="معنی انگلیسی" required maxlength="80"><button class="btn primary" type="submit">ذخیره واژه +</button></form>`}
function renderStats(){let count=units.filter((_,i)=>done(i)).length;return `<button class="back" data-tab="more">→ بیشتر</button><div class="page-head"><h1>🏆 پیشرفت من</h1><p>هر روز یک قدم جلوتر</p></div><div class="stat-grid"><div><b>⭐ ${stars()}</b><span>ستاره</span></div><div><b>🔥 ${streak()}</b><span>روز متوالی</span></div><div><b>${count}/50</b><span>مرحله کامل</span></div><div><b>${db.correct||0}</b><span>پاسخ درست</span></div></div><h2 class="small-title">مرحله‌های من</h2>${units.slice(0,Math.max(5,count+2)).map((u,i)=>`<div class="progress-row"><span>${i+1}. ${esc(u.title)}</span><strong>${prog(i).filter(Boolean).length}/4</strong>${meter(prog(i).filter(Boolean).length*25)}</div>`).join('')}<h2 class="small-title">نیازمند مرور</h2>${db.missed.map(findWord).filter(Boolean).slice(0,15).map(wordRow).join('')||'<div class="empty">هنوز اشتباهی ثبت نشده است.</div>'}`}
const REMINDER_KEY='finnish-reminder-v11';
function reminderEnabled(){try{return localStorage.getItem(REMINDER_KEY)==='on'}catch{return false}}
async function toggleReminder(){if(reminderEnabled()){try{localStorage.setItem(REMINDER_KEY,'off')}catch{}toast('یادآوری خاموش شد');render();return}
 if('Notification'in window&&Notification.permission==='default'){try{await Notification.requestPermission()}catch{}}
 try{localStorage.setItem(REMINDER_KEY,'on')}catch{}toast('یادآوری هنگام استفاده از اپ فعال شد');render()}
async function maybeRemind(){if(!reminderEnabled())return;try{const k='finnish-last-reminder-v11',last=localStorage.getItem(k),now=today();if(last===now)return;if(!document.hidden){localStorage.setItem(k,now);if('Notification'in window&&Notification.permission==='granted'&&'serviceWorker'in navigator){const reg=await navigator.serviceWorker.ready;await reg.showNotification('🇫🇮 وقت تمرین فنلاندی!',{body:'امروز چند دقیقه لغت و بازی تمرین کن.',icon:'./icon-192.png',tag:'finnish-daily-practice'})}else toast('🇫🇮 وقت تمرین فنلاندی!')}}catch{}}
window.addEventListener('focus',maybeRemind);document.addEventListener('visibilitychange',()=>{if(!document.hidden)maybeRemind()});setInterval(maybeRemind,60000);
function renderSettings(){const rem=reminderEnabled();return `<button class="back" data-tab="more">→ بیشتر</button><div class="page-head"><h1>⚙️ تنظیمات</h1></div>${controls()}<div class="setting-card"><h3>🔊 تلفظ</h3><button class="btn secondary" data-action="testVoice">پخش نمونه تلفظ</button><div class="sound-toggle"><span>🎮 صدای بازی‌ها</span><button data-action="toggleGameSound" aria-pressed="${s.gameSound}">${s.gameSound?'روشن':'خاموش'}</button></div></div><div class="setting-card"><h3>🔔 یادآوری تمرین</h3><p>اگر فعالش کنی، هنگام باز بودن اپ یا برگشتن به اپ، یادآوری روزانه می‌بینی.</p><div class="sound-toggle"><span>یادآوری روزانه</span><button data-action="toggleReminder" aria-pressed="${rem}">${rem?'🔔 فعال':'فعال‌کردن'}</button></div><p class="tiny-note">اعلان در زمان بسته‌بودن کامل اپ هنوز فعال نیست؛ برای آن به سرویس ارسال اعلان نیاز است.</p></div><div class="setting-card"><h3>📲 نصب روی آیفون و اندروید</h3><p>لینک اپ را در Safari آیفون یا Chrome اندروید باز کن و از Share / منو گزینه Add to Home Screen یا Install app را بزن.</p></div>`}

const authConfig=window.FINNISH_AUTH_CONFIG||{};
let authClient=null,authUser=null,authError='',authReady=false,isAdmin=false;
let pendingEmail='';try{pendingEmail=localStorage.getItem('finnish-pending-email')||''}catch{}
function setPendingEmail(v){pendingEmail=v;try{if(v)localStorage.setItem('finnish-pending-email',v);else localStorage.removeItem('finnish-pending-email')}catch{}}
let ticketList=[],activeTicket=null,ticketMessages=[],supportBusy=false,authRecovery=false;
const supportEnabled=()=>window.FINNISH_SUPPORT_ENABLED===true;
 const configured=()=>/^https:\/\/[a-z0-9-]+\.supabase\.co\/?$/i.test(authConfig.url||'')&&String(authConfig.anonKey||'').length>35;
async function getAuthClient(){
 if(!configured())throw Error('برای فعال‌سازی حساب و تیکت، تنظیمات Supabase باید تکمیل شود.');
 if(authClient)return authClient;
 if(!window.supabase){await new Promise((resolve,reject)=>{let el=document.createElement('script');el.src='https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.min.js';el.onload=resolve;el.onerror=()=>reject(Error('اتصال به سرویس حساب برقرار نشد'));document.head.appendChild(el)})}
 authClient=window.supabase.createClient(authConfig.url,authConfig.anonKey,{auth:{autoRefreshToken:true,persistSession:true,detectSessionInUrl:true}});
 authClient.auth.onAuthStateChange((event,session)=>{
   authUser=session?.user?.email_confirmed_at?session.user:null;if(authUser)setPendingEmail('');
   if(event==='PASSWORD_RECOVERY')authRecovery=true;
   if(event==='SIGNED_OUT'){isAdmin=false;ticketList=[];activeTicket=null;ticketMessages=[];}
   if(event==='SIGNED_IN')setTimeout(()=>{if(supportEnabled())loadAdminFlag().then(()=>{if(s.tab==='support')loadTickets();if(['profile','account'].includes(s.tab))render()}).catch(()=>{});else if(['profile','account'].includes(s.tab))render()},0);if(['SIGNED_IN','SIGNED_OUT','PASSWORD_RECOVERY'].includes(event))setTimeout(()=>{if(['profile','account','support','ticket','adminTickets'].includes(s.tab))render();},0);
 });
 return authClient;
}
async function initAuth(){if(!configured())return;try{let c=await getAuthClient();let {data:sessionData}=await c.auth.getSession();authUser=sessionData.session?.user?.email_confirmed_at?sessionData.session.user:null;if(authUser){const {data:userData,error}=await c.auth.getUser();if(!error&&userData.user?.email_confirmed_at)authUser=userData.user;if(authUser)setPendingEmail('');}if(supportEnabled())await loadAdminFlag();}catch(e){authError=String(e.message||e)}finally{authReady=true;if(['profile','account','support','ticket','adminTickets'].includes(s.tab))render();}}
async function loadAdminFlag(){isAdmin=false;if(!supportEnabled()||!authUser||!authClient)return;let {data,error}=await authClient.rpc('is_support_admin');if(!error)isAdmin=!!data;}
function supportError(e){let m=String(e?.message||e||'خطای نامشخص');if(/Invalid login credentials/i.test(m))return 'ایمیل یا رمز عبور درست نیست.';if(/Email not confirmed/i.test(m))return 'اول ایمیلت را تأیید کن.';if(/email rate limit/i.test(m))return 'تعداد ایمیل‌های ارسالی زیاد شده؛ بعداً دوباره تلاش کن.';if(/permission denied|API DISABLED|42501/i.test(m))return 'دسترسی پایگاه داده پشتیبانی هنوز فعال نیست.';if(/relation.*does not exist|Could not find the table/i.test(m))return 'پایگاه داده تیکت هنوز راه‌اندازی نشده است.';return m.slice(0,180)}
const AVATARS=['👩🏻‍🎓','👨🏻‍🎓','🦊','🐻','🐼','🦉','🌸','🇫🇮'];
const AVATAR_KEY='finnish-profile-avatar-v11';
function savedAvatar(){try{return JSON.parse(localStorage.getItem(AVATAR_KEY)||'null')||{type:'icon',value:'👤'}}catch{return {type:'icon',value:'👤'}}}
function saveAvatar(value){try{localStorage.setItem(AVATAR_KEY,JSON.stringify(value))}catch{toast('ذخیره عکس انجام نشد')}render()}
function userProfile(){const m=authUser?.user_metadata||{};return {name:esc(m.full_name||m.name||authUser?.email?.split('@')[0]||'زبان‌آموز'),email:esc(authUser?.email||'')}}
function renderProfile(){
 const p=userProfile(),completed=units.filter((_,i)=>done(i)).length,sections=units.reduce((n,_,i)=>n+prog(i).filter(Boolean).length,0),av=savedAvatar();
 const avatar=av.type==='photo'&&/^data:image\/(?:jpeg|png|webp);base64,/.test(av.value)?`<img src="${av.value}" alt="عکس پروفایل">`:esc(av.value||'👤');
 return `<button class="back" data-tab="more">→ بیشتر</button><div class="page-head"><h1>👤 پروفایل من</h1></div><section class="profile-hero"><div class="profile-avatar">${avatar}</div><h2>${authUser?p.name:'مهمان'}</h2>${authUser?`<span class="profile-status">✓ حساب تأییدشده</span><small dir="ltr">${p.email}</small>`:'<p>برای دسترسی به بخش‌های بیشتر، ثبت‌نام کن.</p>'}</section>
 ${authUser?`<div class="setting-card"><h3>🖼️ عکس یا آیکن پروفایل</h3><div class="avatar-options">${AVATARS.map((icon,i)=>`<button data-avatar-icon="${i}" aria-label="انتخاب آیکن ${i+1}">${icon}</button>`).join('')}</div><button class="btn secondary" data-action="chooseAvatar">📷 انتخاب عکس از گوشی</button><p class="tiny-note">عکس و آیکن فقط روی همین گوشی ذخیره می‌شوند.</p></div><div class="stat-grid profile-stats"><div><b>⭐ ${stars()}</b><span>امتیاز</span></div><div><b>🔥 ${streak()}</b><span>روز متوالی</span></div><div><b>${completed}/50</b><span>درس کامل</span></div><div><b>${sections}/200</b><span>بخش کامل</span></div></div><div class="setting-card"><h3>📊 پیشرفت من</h3>${meter(sections/200*100)}<button class="btn secondary" data-tab="stats">جزئیات پیشرفت</button></div><div class="setting-card"><h3>حساب کاربری</h3><button class="btn secondary" data-action="logout">خروج از حساب</button></div>`:
 `<div class="setting-card"><h3>✉️ ثبت‌نام یا ورود با ایمیل</h3>${renderEmailAuthForm()}</div>`}`;
}
function renderEmailAuthForm(){return `${!configured()?'<p>اتصال حساب کاربری هنوز تنظیم نشده است.</p>':`<form id="authForm" class="custom-form"><label for="authEmail">ایمیل</label><input id="authEmail" type="email" autocomplete="email" dir="ltr" placeholder="name@example.com" required><label for="authPassword">رمز عبور (حداقل ۸ کاراکتر)</label><input id="authPassword" type="password" autocomplete="current-password" minlength="8" required><div class="auth-actions"><button class="btn primary" name="intent" value="signup" type="submit">ثبت‌نام</button><button class="btn secondary" name="intent" value="login" type="submit">ورود</button></div></form><button class="text-link" data-action="resetPassword">رمز عبور را فراموش کرده‌ام</button>${pendingEmail?`<div class="verify-notice"><strong>📩 لطفاً ایمیلت را تأیید کن</strong><p>لینک تأیید به <span dir="ltr">${esc(pendingEmail)}</span> ارسال شده است. بعد از تأیید، به اپ برگرد و وارد شو.</p><button class="btn secondary" data-action="resendConfirmation">ارسال دوباره ایمیل تأیید</button></div>`:''}`}`}
function renderAccount(){return `<button class="back" data-tab="profile">→ پروفایل من</button><div class="page-head"><h1>✉️ حساب کاربری</h1></div>${authRecovery?`<form id="newPasswordForm" class="custom-form"><label>رمز جدید</label><input id="newPassword" type="password" minlength="8" required><button class="btn primary" type="submit">ذخیره رمز</button></form>`:authUser?`<div class="setting-card"><h3>حساب تأییدشده</h3><p>${esc(authUser.email||'')}</p><button data-tab="profile" class="btn primary">پروفایل من</button></div>`:`<div class="setting-card">${renderEmailAuthForm()}</div>`}`}
function ticketStatus(status){return status==='closed'?'بسته شده':status==='answered'?'پاسخ داده شده':'در انتظار پاسخ'}
function ticketRow(t){return `<button class="ticket-row" data-ticket="${esc(t.id)}"><span><strong>${esc(t.subject)}</strong><small>${new Date(t.created_at).toLocaleDateString('fa-IR')} · ${ticketStatus(t.status)}</small></span><b>←</b></button>`}
function renderSupport(){if(!supportEnabled())return `<button class="back" data-tab="more">→ بیشتر</button><div class="notice">پشتیبانی آنلاین در حال آماده‌سازی است. فعلاً از درس‌ها و بازی‌ها استفاده کن.</div>`;return `<button class="back" data-tab="more">→ بیشتر</button><div class="page-head"><h1>💬 پشتیبانی و تیکت</h1><p>سؤال، پیشنهاد یا گزارش مشکل را خصوصی بفرست و پاسخ را در همین‌جا بخوان.</p></div>${!configured()?`<div class="setting-card"><h3>در انتظار راه‌اندازی</h3><p>سیستم تیکت هنوز به دیتابیس متصل نشده است. بعد از فعال‌سازی، پیام‌ها داخل اپ ثبت می‌شوند و ایمیل پشتیبانی نمایش داده نمی‌شود.</p></div>`:!authUser?`<div class="setting-card"><h3>🔒 برای ارسال تیکت وارد شو</h3><p>برای اینکه بتوانی پاسخ را پیگیری کنی، باید با ایمیل خودت وارد حساب شوی.</p><button class="btn primary" data-tab="account">ورود یا ثبت‌نام</button></div>`:`<div class="setting-card"><h3>✉️ تیکت جدید</h3><form id="supportForm" class="custom-form"><label for="supportTopic">موضوع</label><input id="supportTopic" maxlength="100" minlength="3" placeholder="مثلاً مشکل تلفظ حرف Ä" required><label for="supportBody">متن پیام</label><textarea id="supportBody" rows="5" minlength="10" maxlength="2000" placeholder="مشکل را توضیح بده…" required></textarea><button class="btn primary" type="submit" ${supportBusy?'disabled':''}>${supportBusy?'در حال ارسال…':'ارسال تیکت'}</button></form></div><h2 class="small-title">📬 تیکت‌های من</h2>${ticketList.length?ticketList.map(ticketRow).join(''):'<div class="empty">هنوز تیکتی ثبت نکرده‌ای.</div>'}<button class="btn secondary" data-action="refreshTickets">↻ تازه‌سازی پیام‌ها</button>${isAdmin?'<button class="btn secondary" data-tab="adminTickets">🛡️ پنل مدیریت تیکت‌ها</button>':''}`}`}
function renderTicket(){if(!authUser)return renderSupport();let t=activeTicket;if(!t)return `<button class="back" data-tab="support">→ تیکت‌ها</button><div class="empty">تیکت انتخاب نشده است.</div>`;return `<button class="back" data-tab="${isAdmin?'adminTickets':'support'}">→ بازگشت به تیکت‌ها</button><div class="page-head"><h1>🎫 ${esc(t.subject)}</h1><p>شماره تیکت: <span dir="ltr">${esc(t.id.slice(0,8).toUpperCase())}</span> · ${ticketStatus(t.status)}</p></div><div class="ticket-thread">${ticketMessages.map(m=>`<div class="ticket-message ${m.author_id===authUser.id?'mine':'theirs'}"><small>${m.author_id===authUser.id?'شما':isAdmin&&m.author_id===t.user_id?'کاربر':'پشتیبانی'} · ${new Date(m.created_at).toLocaleString('fa-IR')}</small><p>${esc(m.body)}</p></div>`).join('')||'<div class="empty">پیامی وجود ندارد.</div>'}</div>${t.status!=='closed'||isAdmin?`<form id="replyForm" class="custom-form"><label>پاسخ جدید</label><textarea id="replyBody" rows="4" minlength="2" maxlength="2000" placeholder="پیام خود را بنویس…" required></textarea><button class="btn primary" type="submit" ${supportBusy?'disabled':''}>ارسال پاسخ</button></form>`:'<div class="notice">این تیکت بسته شده است.</div>'}${isAdmin?`<button class="btn secondary" data-action="toggleTicketStatus">${t.status==='closed'?'باز کردن دوباره تیکت':'بستن تیکت'}</button>`:''}<button class="btn secondary" data-action="refreshTicket">↻ بررسی پاسخ جدید</button>`}
function renderAdminTickets(){if(!isAdmin)return renderSupport();return `<button class="back" data-tab="more">→ بیشتر</button><div class="page-head"><h1>🛡️ مدیریت پشتیبانی</h1><p>تیکت‌های کاربران · فقط مدیر مجاز</p></div>${ticketList.length?ticketList.map(ticketRow).join(''):'<div class="empty">تیکتی برای نمایش نیست.</div>'}<button class="btn secondary" data-action="refreshTickets">↻ تازه‌سازی تیکت‌ها</button>`}
async function submitAuth(e){e.preventDefault();let email=$('#authEmail')?.value.trim(),password=$('#authPassword')?.value,intent=e.submitter?.value||'signup';if(!email||!password)return;try{let c=await getAuthClient();let {data,error}=intent==='signup'?await c.auth.signUp({email,password,options:{emailRedirectTo:location.origin+location.pathname}}):await c.auth.signInWithPassword({email,password});if(error)throw error;if(data.session?.user?.email_confirmed_at){authUser=data.session.user;setPendingEmail('');toast('خوش آمدی!');go('profile')}else{authUser=null;setPendingEmail(email);go('profile');toast('لطفاً ایمیلت را تأیید کن')} }catch(e){let message=supportError(e);if(/تأیید کن/.test(message)){setPendingEmail(email);go('profile')}toast(message)}}
async function resendConfirmation(){if(!pendingEmail)return;try{let c=await getAuthClient();let {error}=await c.auth.resend({type:'signup',email:pendingEmail,options:{emailRedirectTo:location.origin+location.pathname}});if(error)throw error;toast('ایمیل تأیید دوباره ارسال شد')}catch(e){toast(supportError(e))}}
async function sendPasswordReset(){let email=prompt('ایمیل حساب خودت را وارد کن:');if(!email)return;try{let c=await getAuthClient();let {error}=await c.auth.resetPasswordForEmail(email.trim(),{redirectTo:location.origin+location.pathname});if(error)throw error;toast('اگر حساب وجود داشته باشد، لینک بازیابی ایمیل می‌شود.')}catch(e){toast(supportError(e))}}
async function updatePassword(e){e.preventDefault();try{let c=await getAuthClient();let {error}=await c.auth.updateUser({password:$('#newPassword').value});if(error)throw error;authRecovery=false;toast('رمز جدید ذخیره شد');render()}catch(e){toast(supportError(e))}}
async function loadTickets(){if(!supportEnabled()||!authUser||!configured())return;try{let c=await getAuthClient();let {data,error}=await c.from('support_tickets').select('id,subject,status,created_at,user_id').order('created_at',{ascending:false}).limit(isAdmin?100:40);if(error)throw error;ticketList=data||[];if(['support','adminTickets'].includes(s.tab))render();}catch(e){toast('تیکت‌ها: '+supportError(e))}}
async function openTicket(id){if(!authUser)return;try{let c=await getAuthClient();let {data:t,error:e1}=await c.from('support_tickets').select('id,subject,status,created_at,user_id').eq('id',id).single();if(e1)throw e1;let {data:ms,error:e2}=await c.from('support_messages').select('id,author_id,body,created_at').eq('ticket_id',id).order('created_at',{ascending:true}).limit(200);if(e2)throw e2;activeTicket=t;ticketMessages=ms||[];go('ticket')}catch(e){toast('باز کردن تیکت: '+supportError(e))}}
async function submitSupport(e){e.preventDefault();if(supportBusy||!authUser)return;let title=$('#supportTopic')?.value.trim(),body=$('#supportBody')?.value.trim();if(!title||!body)return;supportBusy=true;try{let c=await getAuthClient();let {data:t,error:e1}=await c.from('support_tickets').insert({user_id:authUser.id,subject:title}).select('id').single();if(e1)throw e1;let {error:e2}=await c.from('support_messages').insert({ticket_id:t.id,author_id:authUser.id,body});if(e2)throw e2;toast('تیکت با موفقیت ثبت شد');await loadTickets();await openTicket(t.id)}catch(e){toast('ارسال تیکت: '+supportError(e))}finally{supportBusy=false}}
async function submitReply(e){e.preventDefault();if(supportBusy||!activeTicket||!authUser)return;let body=$('#replyBody')?.value.trim();if(!body)return;supportBusy=true;try{let c=await getAuthClient();let {error}=await c.from('support_messages').insert({ticket_id:activeTicket.id,author_id:authUser.id,body});if(error)throw error;if(isAdmin){await c.from('support_tickets').update({status:'answered'}).eq('id',activeTicket.id)}toast('پاسخ ارسال شد');await openTicket(activeTicket.id)}catch(e){toast(supportError(e))}finally{supportBusy=false}}
async function toggleTicketStatus(){if(!isAdmin||!activeTicket)return;let newStatus=activeTicket.status==='closed'?'open':'closed';let {error}=await authClient.from('support_tickets').update({status:newStatus}).eq('id',activeTicket.id);if(error)return toast(supportError(error));await openTicket(activeTicket.id)}
function renderScan(){return `<button class="back" data-tab="more">→ بیشتر</button><div class="page-head"><h1>📷 دوربین لغات</h1><p>از نوشته فنلاندی روی محصول عکس بگیر و واژه‌های موجود در فرهنگ داخلی اپ را پیدا کن.</p></div><div class="camera-box"><div class="camera-illustration">📸</div><h2>از محصول عکس بگیر</h2><p>نور کافی و نوشته واضح نتیجه بهتری می‌دهد.</p><div class="camera-buttons"><button data-action="camera" class="btn primary">📷 دوربین</button><button data-action="gallery" class="btn secondary">🖼️ گالری</button></div></div>${s.scanUrl?`<img class="scan-preview" src="${s.scanUrl}" alt="تصویر انتخاب‌شده">${button(s.busy?'در حال خواندن تصویر…':'🔍 شناسایی نوشته','ocr','primary')}`:''}${s.busy?'<div class="scan-status">در حال بارگیری موتور تشخیص متن و شناسایی نوشته…</div>':''}${s.scanText?`<h2 class="small-title">کلمات پیدا شده (${s.matches.length})</h2>${s.matches.length?s.matches.map(wordRow).join(''):'<div class="empty">واژه‌ای مطابق فرهنگ داخلی پیدا نشد.</div>'}<details><summary>نمایش متن خوانده‌شده</summary><p dir="ltr">${esc(s.scanText)}</p></details>`:''}<h2 class="small-title">جست‌وجوی دستی</h2><input id="lookup" class="answer-input" placeholder="مثلاً maito یا شیر" value="${esc(s.search)}"><div id="lookupResults">${renderLookup()}</div><p class="disclaimer">OCR در اولین استفاده به اینترنت نیاز دارد و دقت آن تضمینی نیست. معنی‌ها فقط از واژه‌نامه داخلی نمایش داده می‌شوند؛ عکس برای ترجمه به سرور اپ ارسال نمی‌شود.</p>`}
function renderLookup(){if(!s.search.trim())return '';let q=norm(s.search);let w=words().filter(w=>norm(w.fi).includes(q)||norm(w.fa).includes(q)||norm(w.en).includes(q)).slice(0,12);return w.length?w.map(wordRow).join(''):'<div class="empty">در فرهنگ داخلی پیدا نشد.</div>'}
function render(){navUpdate();headerUpdate();let routes={home:renderHome,path:renderPath,lesson:renderLesson,practice:renderPractice,games:renderGames,mini:renderMini,category:renderCategories,categoryDetail:renderCategory,grammar:renderGrammar,grammarDetail:renderGrammarDetail,quiz:renderQuiz,more:renderMore,saved:renderSaved,stats:renderStats,settings:renderSettings,profile:renderProfile,account:renderAccount,support:renderSupport,ticket:renderTicket,adminTickets:renderAdminTickets,scan:renderScan};app.innerHTML=(routes[s.tab]||renderHome)();app.classList.remove('screen-enter');void app.offsetWidth;app.classList.add('screen-enter')}
function onNext(){s.q++;s.choice=null;s.typing='';if(s.gameType==='spell'&&s.tab==='mini'&&s.q<s.questions.length)setupSpell();if(s.q>=s.questions.length){if(s.tab==='mini'){s.passed=s.score>=Math.min(4,s.questions.length);s.finished=true;db.stars+=s.passed?2:0;save();render()}else finishPhase()}else render()}
function onResult(){if(s.tab==='mini'){if(s.passed)go('games');else startMini(s.gameType);return}if(s.passed){if(s.phase===3&&s.unit<units.length-1&&unlocked(s.unit+1)){s.unit++;go('lesson')}else go('lesson')}else beginPhase(s.phase)}
function toggleKnown(id){if(db.known.includes(id))db.known=db.known.filter(x=>x!==id);else db.known.push(id);save();render()}
function toggleSave(id){if(db.saved.includes(id))db.saved=db.saved.filter(x=>x!==id);else db.saved.push(id);save();render()}
function onFile(file){if(!file)return;if(!file.type.startsWith('image/'))return toast('فایل باید عکس باشد');if(file.size>20*1024*1024)return toast('حجم عکس زیاد است');if(s.scanUrl)URL.revokeObjectURL(s.scanUrl);s.scanFile=file;s.scanUrl=URL.createObjectURL(file);s.scanText='';s.matches=[];go('scan')}
function loadOCR(){return new Promise((res,rej)=>{if(window.Tesseract)return res();let e=document.createElement('script');e.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';e.onload=()=>window.Tesseract?res():rej(new Error('OCR unavailable'));e.onerror=rej;document.head.appendChild(e)})}
async function ocr(){if(!s.scanFile||s.busy)return;s.busy=true;render();let worker;try{await loadOCR();worker=await Tesseract.createWorker('fin+eng',1,{logger:m=>{let t=$('.scan-status');if(t&&m.progress!=null)t.textContent='شناسایی متن: '+Math.round(m.progress*100)+'٪'}});let out=await worker.recognize(s.scanFile);s.scanText=(out.data.text||'').trim();let tokens=new Set((s.scanText.match(/[\p{L}]+(?:-[\p{L}]+)*/gu)||[]).map(norm));s.matches=words().filter(w=>tokens.has(norm(w.fi))||norm(w.fi).includes(' ')&&norm(s.scanText).includes(norm(w.fi))).slice(0,35);if(!s.scanText)toast('متنی پیدا نشد؛ عکس واضح‌تری بگیر');touch()}catch(e){console.error(e);toast('اسکن انجام نشد؛ اینترنت یا دسترسی دوربین را بررسی کن')}finally{if(worker)try{await worker.terminate()}catch{}s.busy=false;render()}}
app.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.speak){speech(b.dataset.speak);return}if(b.dataset.avatarIcon!==undefined){saveAvatar({type:'icon',value:AVATARS[+b.dataset.avatarIcon]});return}if(b.dataset.quizLevel){if(!authUser&&b.dataset.quizLevel!=='A1'){go('profile');return}startQuiz('level',b.dataset.quizLevel);return}if(b.dataset.quizReview){if(!authUser){go('profile');return}startQuiz('review',s.quizLevel);return}if(b.dataset.quizAnswer){quizAnswer(b.dataset.quizAnswer);return}if(b.dataset.ticket){openTicket(b.dataset.ticket);return}if(b.dataset.memory!==undefined){flipMemory(+b.dataset.memory);return}if(b.dataset.truefalse){const p=s.truePairs[s.q];answer((b.dataset.truefalse==='yes')===p.correct?s.questions[s.q].w.id:'wrong');return}if(b.dataset.letter!==undefined){if(s.choice===null&&!s.spellPicked.includes(+b.dataset.letter)){s.spellPicked.push(+b.dataset.letter);render()}return}if(b.dataset.speed){s.speed=b.dataset.speed;try{localStorage.setItem('finnish-speed-v11',s.speed)}catch{}render();return}if(b.dataset.tab){go(b.dataset.tab);if(['support','adminTickets'].includes(b.dataset.tab)){if(configured()&&!authReady)initAuth().then(loadTickets);else loadTickets()}return}if(b.dataset.unit!==undefined){s.unit=+b.dataset.unit;go('lesson');return}if(b.dataset.phase!==undefined){beginPhase(+b.dataset.phase);return}if(b.dataset.answer){answer(b.dataset.answer);return}if(b.dataset.known){toggleKnown(b.dataset.known);return}if(b.dataset.save){toggleSave(b.dataset.save);return}if(b.dataset.filter){s.filter=b.dataset.filter;render();return}if(b.dataset.cat){if(!authUser&&categorySets().findIndex(x=>x.id===b.dataset.cat)>0){go('profile');return}s.cat=b.dataset.cat;s.filter='all';go('categoryDetail');return}if(b.dataset.grammar!==undefined){if(!authUser&&+b.dataset.grammar>0){go('profile');return}s.grammar=+b.dataset.grammar;go('grammarDetail');return}if(b.dataset.game){if(!authUser&&b.dataset.game!=='match'){go('profile');return}startMini(b.dataset.game);return}
switch(b.dataset.action){case 'continue':s.unit=nextUnit();go('lesson');break;case 'backLesson':go('lesson');break;case 'knowNext':if(s.wi+1<unitWords().length){s.wi++;render()}else{let p=prog(s.unit);if(!p[0]){p[0]=true;db.stars+=2;touch()}toast('آموزش کامل شد! بخش شنیداری باز شد');go('lesson')}break;case 'nextQuestion':onNext();break;case 'quizNext':quizNext();break;case 'quizAgain':startQuiz(s.quizMode,s.quizLevel);break;case 'quizSame':startQuiz(s.quizMode,s.quizLevel,true);break;case 'miniAgain':startMini(s.gameType);break;case 'miniSame':startMini(s.gameType,true);break;case 'miniBack':go('games');break;case 'quizReview':startQuiz('review',s.quizLevel);break;case 'resultNext':onResult();break;case 'camera':$('#cameraInput').click();break;case 'gallery':$('#galleryInput').click();break;case 'ocr':ocr();break;case 'testVoice':speech('Hei! Tervetuloa opiskelemaan suomea.');break;case 'enablePush':{
 const ios=/iPhone|iPad|iPod/i.test(navigator.userAgent);
 const installed=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
 if(ios&&!installed){toast('در آیفون، اول سایت را با Safari به صفحه اصلی اضافه کن و از آیکن اپ باز کن.');break;}
 const os=window.finnishOneSignal;
 if(!os){toast('اتصال اعلان‌ها هنوز آماده نیست. اینترنت را بررسی کن و دوباره امتحان کن.');break;}
 if(!('Notification' in window)){toast('این دستگاه یا مرورگر از اعلان‌های وب پشتیبانی نمی‌کند.');break;}
 try{os.Notifications.requestPermission().then(()=>toast(os.Notifications.permission?'اعلان‌ها فعال شدند 🔔':'برای دریافت اعلان‌ها باید اجازه بدهی')).catch(()=>toast('فعال‌سازی اعلان‌ها انجام نشد'));}
 catch(e){toast('فعال‌سازی اعلان‌ها انجام نشد');}
 break;
 }case 'spellBack':s.spellPicked.pop();render();break;case 'spellCheck':{let w=s.questions[s.q].w;let built=s.spellPicked.map(i=>s.spellTiles[i].ch).join('');answer(norm(built)===norm(w.fi)?w.id:'wrong');break}case 'toggleGameSound':s.gameSound=!s.gameSound;try{localStorage.setItem('finnish-game-sound',s.gameSound?'on':'off')}catch{}render();break;case 'logout':if(authClient)authClient.auth.signOut().then(()=>{authUser=null;isAdmin=false;render()});break;case 'resetPassword':sendPasswordReset();break;case 'resendConfirmation':resendConfirmation();break;case 'chooseAvatar':$('#avatarInput').click();break;case 'toggleReminder':toggleReminder();break;case 'refreshTickets':loadTickets();break;case 'refreshTicket':if(activeTicket)openTicket(activeTicket.id);break;case 'toggleTicketStatus':toggleTicketStatus();break;}});
app.addEventListener('input',e=>{if(e.target.id==='writeInput')s.typing=e.target.value;if(e.target.id==='lookup'){s.search=e.target.value;$('#lookupResults').innerHTML=renderLookup()}});
app.addEventListener('submit',e=>{if(e.target.id==='authForm'){submitAuth(e);return}if(e.target.id==='supportForm'){submitSupport(e);return}if(e.target.id==='replyForm'){submitReply(e);return}if(e.target.id==='newPasswordForm'){updatePassword(e);return}if(e.target.id==='writeForm'){e.preventDefault();if(s.choice!==null)return;let w=s.questions[s.q].w;answer(norm(s.typing)===norm(w.fi)?w.id:'wrong');return}if(e.target.id==='customForm'){e.preventDefault();let fi=$('#customFi').value.trim(),fa=$('#customFa').value.trim(),en=$('#customEn').value.trim();if(!fi||!fa||!en)return;let id='custom-'+Date.now();db.custom.push({id,fi,fa,en});db.saved.push(id);save();toast('واژه اضافه شد');render()}});
document.querySelectorAll('.bottom-nav button').forEach(b=>b.addEventListener('click',()=>go(b.dataset.tab)));
$('#profileShortcut')?.addEventListener('click',()=>go('profile'));
$('#avatarInput')?.addEventListener('change',async e=>{let f=e.target.files?.[0];e.target.value='';if(!f)return;if(!f.type.startsWith('image/')||f.size>8*1024*1024)return toast('عکس باید کمتر از ۸ مگابایت باشد');try{const img=await createImageBitmap(f),canvas=document.createElement('canvas');canvas.width=192;canvas.height=192;const ctx=canvas.getContext('2d');const size=Math.min(img.width,img.height);ctx.drawImage(img,(img.width-size)/2,(img.height-size)/2,size,size,0,0,192,192);img.close?.();saveAvatar({type:'photo',value:canvas.toDataURL('image/jpeg',.78)})}catch(err){toast('خواندن عکس ممکن نشد')}});
$('#cameraInput').addEventListener('change',e=>{onFile(e.target.files?.[0]);e.target.value=''});$('#galleryInput').addEventListener('change',e=>{onFile(e.target.files?.[0]);e.target.value=''});
if('speechSynthesis'in window){speechSynthesis.getVoices();speechSynthesis.onvoiceschanged=()=>speechSynthesis.getVoices()}
if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
render();
initAuth();
})();
